#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>

#define SHIFT 22
#define MASK 0x7FF
#define NEG -1000000000

static int cmp(const void *a, const void *b) {
    uint64_t x = *(const uint64_t *)a;
    uint64_t y = *(const uint64_t *)b;
    if (x < y) return 1;
    if (x > y) return -1;
    return 0;
}

int main(void) {
    int N;
    if (scanf("%d", &N) != 1) return 0;

    int *x = (int *)malloc((size_t)N * sizeof(int));
    int *y = (int *)malloc((size_t)N * sizeof(int));

    for (int i = 0; i < N; ++i) {
        scanf("%d %d", &x[i], &y[i]);
    }

    int E = N * N;
    uint64_t *edges = (uint64_t *)malloc((size_t)E * sizeof(uint64_t));
    int idx = 0;

    for (int v = 1; v <= N; ++v) {
        int xx = x[v - 1];
        int yy = y[v - 1];
        int len = xx * xx + yy * yy;
        edges[idx++] = ((uint64_t)len << SHIFT) | (uint64_t)v;
    }

    for (int u = 1; u <= N; ++u) {
        int xu = x[u - 1];
        int yu = y[u - 1];
        for (int v = 1; v <= N; ++v) {
            if (u == v) continue;
            int dx = xu - x[v - 1];
            int dy = yu - y[v - 1];
            int len = dx * dx + dy * dy;
            edges[idx++] = ((uint64_t)len << SHIFT) | ((uint64_t)u << 11) | (uint64_t)v;
        }
    }

    qsort(edges, (size_t)E, sizeof(uint64_t), cmp);

    int *best = (int *)malloc((size_t)(N + 1) * sizeof(int));
    int *upd = (int *)malloc((size_t)(N + 1) * sizeof(int));
    int *touched = (int *)malloc((size_t)(N + 1) * sizeof(int));

    for (int i = 0; i <= N; ++i) {
        best[i] = NEG;
        upd[i] = NEG;
    }
    best[0] = 0;

    int ans = 0;
    int i = 0;

    while (i < E) {
        int curLen = (int)(edges[i] >> SHIFT);
        int j = i;
        int tcnt = 0;

        while (j < E && (int)(edges[j] >> SHIFT) == curLen) {
            uint64_t e = edges[j];
            int u = (int)((e >> 11) & MASK);
            int v = (int)(e & MASK);

            int bu = best[u];
            if (bu >= 0) {
                int dp = bu + 1;
                if (dp > ans) ans = dp;
                if (dp > upd[v]) {
                    if (upd[v] == NEG) touched[tcnt++] = v;
                    upd[v] = dp;
                }
            }
            ++j;
        }

        for (int k = 0; k < tcnt; ++k) {
            int v = touched[k];
            if (upd[v] > best[v]) best[v] = upd[v];
            upd[v] = NEG;
        }

        i = j;
    }

    printf("%d\n", ans);

    free(x);
    free(y);
    free(edges);
    free(best);
    free(upd);
    free(touched);

    return 0;
}
